// ═══════════════════════════════════════════════════════
// MOTOR DE PREEVALUACIÓN KREDITTON — Parámetros editables
// ═══════════════════════════════════════════════════════
const PARAMETROS = {
  TASA_EA: 0.155,
  MAX_DEUDA_RATIO: 0.40,
  ALTA_LTV_MAX: 0.80,
  ALTA_SCORE_MIN: 700,
  MEDIA_LTV_MAX: 0.90,
  MEDIA_SCORE_MIN: 600,
  SEGURO_VIDA_FACTOR: 1800 / 10000000,
  SEGURO_INCENDIO_APTO: (130 * 0.95) / 1000000,
  SEGURO_INCENDIO_CASA: (150 * 0.85) / 1000000,
};

const d = items[0].json;

// ── Cálculos financieros ────────────────────────────────
const tasaMV = Math.pow(1 + PARAMETROS.TASA_EA, 1/12) - 1;
const cuotaSinSeguro = (tasaMV * d.monto_solicitado) / (1 - Math.pow(1 + tasaMV, -d.plazo_meses));
const seguroVida = d.monto_solicitado * PARAMETROS.SEGURO_VIDA_FACTOR;
const seguroIncendio = d.valor_inmueble * (d.subtipo_inmueble === 'apartamento' ? PARAMETROS.SEGURO_INCENDIO_APTO : PARAMETROS.SEGURO_INCENDIO_CASA);
const cuotaTotal = cuotaSinSeguro + seguroVida + seguroIncendio;
const cuotaMaxima = d.ingresos * PARAMETROS.MAX_DEUDA_RATIO;
const ltv = d.monto_solicitado / d.valor_inmueble;

// ── Score interno (0-100) ───────────────────────────────
let score = 0;
const ratio = cuotaTotal / d.ingresos;
if (ratio <= 0.25) score += 40;
else if (ratio <= 0.30) score += 35;
else if (ratio <= 0.35) score += 25;
else if (ratio <= 0.40) score += 10;

if (ltv <= 0.60) score += 30;
else if (ltv <= 0.70) score += 25;
else if (ltv <= 0.80) score += 20;
else if (ltv <= 0.90) score += 10;

if (d.score_credito >= 750) score += 20;
else if (d.score_credito >= 700) score += 17;
else if (d.score_credito >= 650) score += 12;
else if (d.score_credito >= 600) score += 8;

if (d.documentacion === 'completa') score += 10;
else if (d.documentacion === 'parcial') score += 5;
if (d.reportes_negativos) score = Math.max(0, score - 15);

// ── Viabilidad ──────────────────────────────────────────
let viabilidad;
if (cuotaTotal > cuotaMaxima || ltv > PARAMETROS.MEDIA_LTV_MAX || d.score_credito < PARAMETROS.MEDIA_SCORE_MIN || d.reportes_negativos || d.documentacion === 'incompleta') {
  viabilidad = 'Baja';
} else if (cuotaTotal <= cuotaMaxima && ltv <= PARAMETROS.ALTA_LTV_MAX && d.score_credito >= PARAMETROS.ALTA_SCORE_MIN && d.documentacion === 'completa') {
  viabilidad = 'Alta';
} else {
  viabilidad = 'Media';
}

return [{ json: { ...d, cuotaSinSeguro, seguroVida, seguroIncendio, cuotaTotal, cuotaMaxima, ltv, score_interno: score, viabilidad } }];

